CREATE OR REPLACE FUNCTION immich_fork.prevent_cutover_verification_identity_change()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
    BEGIN
      IF TG_OP = 'TRUNCATE' THEN
        IF TG_TABLE_NAME = 'cutover_verification_run' AND EXISTS (
          SELECT 1 FROM immich_fork.cutover_verification_run WHERE status = 'completed'
        ) THEN
          RAISE EXCEPTION 'completed cutover verification run evidence is immutable';
        END IF;
        IF TG_TABLE_NAME = 'cutover_verification_asset' AND EXISTS (
          SELECT 1 FROM immich_fork.cutover_verification_asset WHERE status = 'verified'
        ) THEN
          RAISE EXCEPTION 'completed cutover verification asset evidence is immutable';
        END IF;
        RETURN NULL;
      END IF;
      IF TG_OP = 'DELETE' THEN
        IF TG_TABLE_NAME = 'cutover_verification_run' AND OLD.status = 'completed' THEN
          RAISE EXCEPTION 'completed cutover verification run evidence is immutable';
        END IF;
        IF TG_TABLE_NAME = 'cutover_verification_asset' AND OLD.status = 'verified' THEN
          RAISE EXCEPTION 'completed cutover verification asset evidence is immutable';
        END IF;
        RETURN OLD;
      END IF;
      IF TG_OP = 'INSERT' THEN
        IF TG_TABLE_NAME = 'cutover_verification_asset' AND EXISTS (
          SELECT 1
          FROM immich_fork.cutover_verification_run
          WHERE id = NEW."runId" AND status = 'completed'
        ) THEN
          RAISE EXCEPTION 'completed cutover verification asset evidence is immutable';
        END IF;
        RETURN NEW;
      END IF;
      IF TG_TABLE_NAME = 'cutover_verification_run' AND
         jsonb_build_array(to_jsonb(NEW)->'id', to_jsonb(NEW)->'databaseBackupId', to_jsonb(NEW)->'snapshotId',
           to_jsonb(NEW)->'applicableAssetCount', to_jsonb(NEW)->'createdAt')
         IS DISTINCT FROM
         jsonb_build_array(to_jsonb(OLD)->'id', to_jsonb(OLD)->'databaseBackupId', to_jsonb(OLD)->'snapshotId',
           to_jsonb(OLD)->'applicableAssetCount', to_jsonb(OLD)->'createdAt') THEN
        RAISE EXCEPTION 'cutover verification run identity is immutable';
      END IF;
      IF TG_TABLE_NAME = 'cutover_verification_run' AND OLD.status = 'completed' AND
         to_jsonb(NEW) IS DISTINCT FROM to_jsonb(OLD) THEN
        RAISE EXCEPTION 'completed cutover verification run evidence is immutable';
      END IF;
      IF TG_TABLE_NAME = 'cutover_verification_asset' AND
         jsonb_build_array(to_jsonb(NEW)->'runId', to_jsonb(NEW)->'assetId', to_jsonb(NEW)->'path',
           to_jsonb(NEW)->'approvedRoots', to_jsonb(NEW)->'expectedSize', to_jsonb(NEW)->'expectedSha1',
           to_jsonb(NEW)->'expectedSha256')
         IS DISTINCT FROM
         jsonb_build_array(to_jsonb(OLD)->'runId', to_jsonb(OLD)->'assetId', to_jsonb(OLD)->'path',
           to_jsonb(OLD)->'approvedRoots', to_jsonb(OLD)->'expectedSize', to_jsonb(OLD)->'expectedSha1',
           to_jsonb(OLD)->'expectedSha256') THEN
        RAISE EXCEPTION 'cutover verification asset identity is immutable';
      END IF;
      IF TG_TABLE_NAME = 'cutover_verification_asset' AND OLD.status = 'verified' AND
         to_jsonb(NEW) IS DISTINCT FROM to_jsonb(OLD) THEN
        RAISE EXCEPTION 'completed cutover verification asset evidence is immutable';
      END IF;
      RETURN NEW;
    END
    $function$

CREATE OR REPLACE FUNCTION public.album_parent_cycle_check()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
    BEGIN
      -- Setting parent to self is always a cycle.
      IF NEW."parentId" IS NOT NULL AND NEW."parentId" = NEW.id THEN
        RAISE EXCEPTION 'Album % cannot be its own parent', NEW.id;
      END IF;
      -- New parent must not already be a descendant of this album (excluding the
      -- self-row, which is always present per closure semantics).
      IF NEW."parentId" IS NOT NULL AND EXISTS (
        SELECT 1
        FROM album_closure
        WHERE id_ancestor = NEW.id
          AND id_descendant = NEW."parentId"
          AND id_ancestor <> id_descendant
      ) THEN
        RAISE EXCEPTION 'Album % cannot have % as parent (would create a cycle)', NEW.id, NEW."parentId";
      END IF;
      RETURN NEW;
    END;
    $function$

CREATE OR REPLACE FUNCTION public.updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
    DECLARE
        clock_timestamp TIMESTAMP := clock_timestamp();
    BEGIN
        new."updatedAt" = clock_timestamp;
        new."updateId" = immich_uuid_v7(clock_timestamp);
        return new;
    END;
  $function$
